    ($SATQ$eccbf957$SATQ$, $SATQ$444b9b7a-9594-422f-b8a2-4e0df96ad5da$SATQ$::uuid, $SATQ$d1c9c48a-1764-424a-ba2b-baece6acd4d2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.E.$SATQ$, $SATQ$Probability and conditional probability$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">Each face of a fair <math alttext="14"><mn>14</mn>
